import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';

/**
 * @typedef {Object} NodeConfig
 * @property {number[]} position
 * @property {number[]} rotation
 * @property {number[]} scale
 * @property {Object} assets
 * @property {string} assets.imageUrl
 * @property {string} textContent
 * @property {Object[]} cinematicPrimitives
 * @property {Object} colors
 * @property {Object} atlasRegion
 */

/**
 * @typedef {Object} NodeContext
 * @property {{ load: (url:string)=>THREE.Texture }} textureLoader
 * @property {{ [key:string]: (obj:THREE.Object3D, params:any)=>void }} primitives
 * @property {{ createText: (opts:any)=>THREE.Object3D }} fontAtlas
 */

/**
 * Creates a pricing card label node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // ----- root container ----------------------------------------------------
  const root = new THREE.Object3D();

  // ----- texture -----------------------------------------------------------
  const tex = ctx.textureLoader.load(config.assets?.imageUrl ?? '');

  // ----- material -----------------------------------------------------------
  const material = new MeshBasicNodeMaterial({ map: tex });

  // ----- geometry (plane) ---------------------------------------------------
  const atlasW = config.atlasRegion?.width ?? 512;
  const atlasH = config.atlasRegion?.height ?? 320;
  const aspect = atlasW / atlasH;
  const geometry = new THREE.PlaneGeometry(aspect, 1);

  // ----- mesh ---------------------------------------------------------------
  const plane = new THREE.Mesh(geometry, material);
  if (Array.isArray(config.position)) plane.position.set(...config.position);
  if (Array.isArray(config.rotation)) plane.rotation.set(...config.rotation);
  if (Array.isArray(config.scale)) plane.scale.set(...config.scale);
  root.add(plane);

  // ----- text (using font atlas) -------------------------------------------
  let textNode = null;
  if (config.textContent) {
    const txtOpts = {
      text: config.textContent,
      // font selection could be refined; using generic keys
      font: 'display',
      size: 0.34, // headline unit height
      color: config.colors?.ink ?? '#16161d',
      rect: {
        x: config.atlasRegion?.x ?? 0,
        y: config.atlasRegion?.y ?? 0,
        width: atlasW,
        height: atlasH,
      },
    };
    textNode = ctx.fontAtlas.createText(txtOpts);
    // Slightly offset in front of the plane so it is visible
    textNode.position.set(0, 0, 0.01);
    plane.add(textNode);
  }

  // ----- cinematic primitives (none in this spec, but keep generic) -------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives?.[prim.name];
      if (typeof fn === 'function') {
        fn(root, prim.params);
      }
    }
  }

  // ----- userData -----------------------------------------------------------
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    // Dispose geometry & material
    geometry.dispose();
    material.dispose();

    // Dispose texture if it is not cached elsewhere
    if (tex && typeof tex.dispose === 'function') {
      tex.dispose();
    }

    // Cleanup text node if it provided a cleanup method
    if (textNode && typeof textNode.userData?.cleanup === 'function') {
      textNode.userData.cleanup();
    }

    // Kill any GSAP timelines that might have been created (none here)
    gsap.globalTimeline.clear();
  };

  return root;
}
